542         function stepToTimeString(step) {{
543             const totalMinutes = step * 5;
544             const hours = Math.floor(totalMinutes / 60);
545             const mins = totalMinutes % 60;
546             const ampm = hours >= 12 ? 'PM' : 'AM';
547             const displayHours = hours % 12 === 0 ? 12 : hours % 12;
548             const displayMins = mins < 10 ? '0' + mins : mins;
549             
550             let rushLabel = '';
551             if ((hours >= 7 && hours <= 9) || (hours >= 16 && hours <= 18)) {{
552                 rushLabel = ' (🚗 Rush Hour)';
553             }} else if (hours >= 0 && hours <= 5) {{
554                 rushLabel = ' (🌙 Off-Peak)';
555             }}
556             return `${{displayHours}}:${{displayMins}} ${{ampm}}${{rushLabel}}`;
557         }}
