559         function onTimeSliderChange(val) {{
560             currentStep = parseInt(val);
561             document.getElementById('step-display').innerText = currentStep;
562             document.getElementById('time-display').innerText = stepToTimeString(currentStep);
563             
564             // Extract Selected Calendar Date
565             const dateVal = document.getElementById('date-picker').value || '2012-03-15';
566             const dateObj = new Date(dateVal);
567             const dayOfWeek = dateObj.getDay(); // 0 = Sun, 6 = Sat
568             const dayOfMonth = dateObj.getDate();
569             const isWeekend = (dayOfWeek === 0 || dayOfWeek === 6);
570             
571             const strKey = String(dayOfWeek % (Object.keys(empiricalProfiles).length || 7));
572             const empDayData = (hasEmpiricalData && (empiricalProfiles[strKey] || empiricalProfiles[dayOfWeek])) ? (empiricalProfiles[strKey] || empiricalProfiles[dayOfWeek]) : null;
573             const empStepSpeeds = (empDayData && empDayData[currentStep]) ? empDayData[currentStep] : null;
574             
575             // Date-dependent traffic factor
576             const dateMult = isWeekend ? 0.45 : 1.0;
577             const dateOffset = (dayOfMonth % 5 - 2) * 0.8;
578             
579             // Dynamic Time-of-Day Traffic & Health Simulation
580             const totalMins = currentStep * 5;
581             const hour = totalMins / 60.0;
582             const rushFactor = (Math.exp(-Math.pow(hour - 8.0, 2) / 4.0) + Math.exp(-Math.pow(hour - 17.5, 2) / 4.0)) * dateMult;
583             
584             // Horizon-based error scaling: 30-min = +25%, 60-min = +55% over 15-min
585             const horizonErrorScale = (activeHorizon === 60) ? 1.55 : (activeHorizon === 30) ? 1.25 : 1.0;
586             // Horizon-based reliability penalty: longer horizons suffer more propagation noise
587             const horizonReliabilityPenalty = (activeHorizon === 60) ? 0.06 : (activeHorizon === 30) ? 0.03 : 0.0;
588             // RSF worsens at longer horizons (spatial disparity widens)
589             const horizonRSFScale = (activeHorizon === 60) ? 1.30 : (activeHorizon === 30) ? 1.12 : 1.0;
590             
591             let sumZeros = 0;
592             let cntH = 0, cntD = 0, cntF = 0;
