594             sensors.forEach((s, idx) => {{
595                 if (!s.baseError) s.baseError = s.error || 2.44;
596                 
597                 // Read Exact Empirical Speed from his.npz if available
598                 if (empStepSpeeds && empStepSpeeds[idx] !== undefined) {{
599                     s.speed = Math.max(0.0, Math.min(70.0, empStepSpeeds[idx]));
600                 }} else {{
601                     const nodeVar = ((s.id * 17 + dayOfMonth) % 7 - 3);
602                     s.speed = Math.max(0.0, Math.min(70.0, 62.0 - rushFactor * 22.0 + nodeVar + dateOffset));
603                 }}
604                 
605                 // Respect Injected Fault Override State
606                 if (s.injectedFault === 'drift') {{
607                     s.reliability = Math.max(0.50, 0.80 - horizonReliabilityPenalty);
608                     s.zero_rate = 18.5;
609                     s.color = '#f1c40f';
610                     s.status = 'DEGRADED DRIFT (STIMULUS)';
611                     s.error = s.baseError * 1.35 * horizonErrorScale;
612                     cntD++;
613                 }} else if (s.injectedFault === 'failure') {{
614                     s.reliability = Math.max(0.20, 0.50 - horizonReliabilityPenalty);
615                     s.zero_rate = 45.0;
616                     s.color = '#e74c3c';
617                     s.status = 'HARDWARE FAILURE (STUCK-ZERO)';
618                     s.error = s.baseError * 2.10 * horizonErrorScale;
619                     cntF++;
620                 }} else if (s.speed < 1.0) {{
621                     s.zero_rate = 100.0;
622                     s.reliability = 0.40;
623                     s.color = '#e74c3c';
624                     s.status = 'HARDWARE FAILURE (STUCK-ZERO)';
625                     s.error = s.baseError * horizonErrorScale;
626                     cntF++;
627                 }} else {{
628                     s.zero_rate = Math.min(48.0, Math.max(0.0, 100.0 * (1.0 - s.speed / 70.0) * 0.25));
629                     s.reliability = Math.max(0.45, Math.min(0.98, s.speed / 70.0 + 0.15 - horizonReliabilityPenalty));
630                     s.error = s.baseError * horizonErrorScale;
631                     
632                     if (s.reliability >= 0.90) {{
