838         function runIntervention() {{
839             if (selectedSensor) {{
840                 const s = sensors.find(item => item.id === selectedSensor.id);
841                 if (!s) return;
842                 
843                 const oldR = s.reliability;
844                 const rGain = Math.max(0, 0.95 - oldR);
845                 const oldErr = s.error;
846                 const errReduction = 0.613 * (rGain * 2.5);
847                 const newErr = Math.max(0.4, oldErr - errReduction);
848                 const oldStatus = s.status;
849                 
850                 delete s.injectedFault;
851                 s.reliability = 0.95;
852                 s.zero_rate = 2.0;
853                 s.color = '#2ecc71';
854                 s.status = 'HEALTHY (REPAIRED)';
855                 s.error = newErr;
856                 
857                 const circle = markerMap[s.id];
858                 if (circle) circle.setStyle({{ fillColor: s.color }});
859                 renderNodeDetails(s);
860                 onTimeSliderChange(currentStep);
861                 
862                 const pctSaved = oldErr > 0 ? ((oldErr - newErr)/oldErr * 100.0).toFixed(1) : '0.0';
863                 
864                 document.getElementById('sim-result').innerHTML = `
865                     <strong>[NODE #${{s.id}} REPAIR SIMULATION EXECUTED]</strong><br>
866                     • Target Node: <strong>Sensor #${{s.id}} (${{oldStatus}} &rarr; REPAIRED)</strong><br>
867                     • Hardware Health Shift: R_${{s.id}} = <strong>${{(oldR*100).toFixed(1)}}% &rarr; 95.0%</strong> (Pin turned Green)<br>
868                     • Node Forecast Error Shift: <strong>${{oldErr.toFixed(2)}} mph &rarr; ${{newErr.toFixed(2)}} mph</strong><br>
869                     • <em>Causal Direct Effect: Eliminates ${{pctSaved}}% of node forecast error!</em>
870                 `;
871             }} else {{
872                 let sumDegradedR = 0;
873                 let cntDegraded = 0;
874                 sensors.forEach(s => {{
875                     if (s.reliability < 0.90 || s.injectedFault) {{
876                         cntDegraded++;
877                         sumDegradedR += s.reliability;
878                         delete s.injectedFault;
879                         s.reliability = 0.95;
880                         s.zero_rate = 2.0;
881                         s.color = '#2ecc71';
882                         s.status = 'HEALTHY (REPAIRED)';
883                         if (s.baseError) s.error = s.baseError;
884                         const circle = markerMap[s.id];
885                         if (circle) circle.setStyle({{ fillColor: s.color }});
886                     }}
887                 }});
888                 
889                 const currentAvgR = cntDegraded > 0 ? (sumDegradedR / cntDegraded) : 0.88;
890                 // Stressed RSF = before repair (degraded sensors worsen disparity)
891                 const currentRSFStressed = baseRSF * (1.0 + (0.95 - currentAvgR) * 0.80);
892                 // Repaired RSF = after repair (clamped to be >= 0 and <= stressed)
893                 const currentRSFRepaired = Math.max(0.001, Math.min(currentRSFStressed, baseRSF * (1.0 - 0.613 * Math.max(0, 0.95 - currentAvgR))));
894                 const recoveryGainPct = currentRSFStressed > 0 ? (((currentRSFStressed - currentRSFRepaired) / currentRSFStressed) * 100.0).toFixed(2) : '0.00';
895 
896                 onTimeSliderChange(currentStep);
897 
898                 document.getElementById('sim-result').innerHTML = `
899                     <strong>[DISASTER RECOVERY NETWORK REPAIR EXECUTED]</strong><br>
900                     • Upgraded <strong>${{cntDegraded}} degraded/failed sensors</strong> to R=0.95 (All pins turned Green)<br>
901                     • Live Stressed RSF: <strong>${{currentRSFStressed.toFixed(4)}}</strong> &rarr; Repaired RSF: <strong>${{currentRSFRepaired.toFixed(4)}}</strong><br>
902                     • <strong>Net Disaster Recovery Equity Gain: +${{recoveryGainPct}}%</strong><br>
903                     • <em>Causal Attribution: Ctf-IE_R restores network equity from current crisis!</em>
904                 `;
905             }}
